DO $mig$
DECLARE r jsonb; pk text;
BEGIN
  FOR r IN SELECT * FROM jsonb_array_elements('[{"slug":"pulse-berlin","year":"2022","title_de":"PULSE, Berlin","title_en":"PULSE, Berlin","type_de":"Gewerbeneubau","type_en":"New commercial build","loc_de":"Berlin-Friedrichshain","loc_en":"Berlin-Friedrichshain","units_de":"200+ Wohneinheiten","units_en":"200+ residential units","desc_de":"Moderner Gewerbeneubau mit über 200 Wohneinheiten und volldigitaler TCS-Türkommunikation inkl. Video und App-Anbindung.","desc_en":"Modern commercial new build with more than 200 residential units and fully digital TCS door communication including video and app integration.","body_de":"Das PULSE in Berlin-Friedrichshain ist eines der ambitioniertesten Neubauprojekte der Hauptstadt. Auf mehreren Etagen vereint es Wohn-, Gewerbe- und Gemeinschaftsflächen zu einem lebendigen Stadtquartier.\n\nTCS wurde als Systempartner für die gesamte Türkommunikation und Zutrittskontrolle ausgewählt. Über 200 Wohneinheiten wurden mit modernster Video-Sprechanlage ausgestattet, die eine nahtlose Kommunikation zwischen Bewohnern und Besuchern ermöglicht.\n\nBesonderes Highlight ist die vollständige App-Integration: Bewohner können Türrufe direkt auf dem Smartphone entgegennehmen und die Tür von überall aus öffnen. Das System wurde in die bestehende Smart-Home-Infrastruktur eingebunden.","body_en":"PULSE in Berlin-Friedrichshain is one of the most ambitious new building projects in the capital. Across several floors it combines residential, commercial and shared spaces into a vibrant urban quarter.\n\nTCS was selected as the system partner for the entire door communication and access control. More than 200 residential units were equipped with state-of-the-art video intercom systems that enable seamless communication between residents and visitors.\n\nA particular highlight is the full app integration: residents can answer door calls directly on their smartphone and open the door from anywhere. The system was integrated into the existing smart home infrastructure.","hl_de":["Volldigitale Türkommunikation","App-Anbindung für alle Bewohner","Smart-Home-Integration","Zentrale Zutrittsverwaltung"],"hl_en":["Fully digital door communication","App integration for all residents","Smart home integration","Central access management"],"sy_de":["TCS Video-Innenstationen","TCS:BUS-System","TCS App-Gateway","BCM-Zutrittskontrolle"],"sy_en":["TCS video indoor stations","TCS:BUS system","TCS app gateway","BCM access control"]},{"slug":"weidt-park-corner","year":"2021","title_de":"Weidt Park Corner, Berlin Mitte","title_en":"Weidt Park Corner, Berlin Mitte","type_de":"Wohnanlage","type_en":"Residential complex","loc_de":"Berlin-Mitte","loc_en":"Berlin-Mitte","units_de":"85 Wohneinheiten","units_en":"85 residential units","desc_de":"Exklusive Wohnanlage mit integrierter Zutrittskontrolle und moderner Videosprechanlage für höchsten Komfort.","desc_en":"Exclusive residential complex with integrated access control and modern video intercom for the highest level of comfort.","body_de":"Weidt Park Corner in Berlin-Mitte definiert urbanes Wohnen auf höchstem Niveau. Die exklusive Wohnanlage verbindet architektonische Eleganz mit modernster Gebäudetechnik.\n\nTCS hat für dieses Projekt eine maßgeschneiderte Lösung aus Videosprechanlage und Zutrittskontrolle entwickelt. Jede der 85 Wohneinheiten verfügt über eine hochauflösende Video-Innenstation mit Touchscreen-Bedienung.\n\nDas Zutrittskontrollsystem ermöglicht eine komfortable und sichere Zugangsverwaltung – von der Tiefgarage bis zur Wohnungstür. Bewohner nutzen RFID-Transponder oder die TCS-App für den schlüssellosen Zugang.","body_en":"Weidt Park Corner in Berlin-Mitte defines urban living at the highest level. The exclusive residential complex combines architectural elegance with state-of-the-art building technology.\n\nFor this project, TCS developed a tailor-made solution made up of video intercom and access control. Each of the 85 residential units is equipped with a high-resolution video indoor station with touchscreen operation.\n\nThe access control system enables convenient and secure access management – from the underground car park to the apartment door. Residents use RFID transponders or the TCS app for keyless access.","hl_de":["Hochauflösende Video-Innenstationen","RFID-Zutrittskontrolle","Schlüsselloser Zugang via App","Design-Außenstationen"],"hl_en":["High-resolution video indoor stations","RFID access control","Keyless access via app","Design outdoor stations"],"sy_de":["TCS Video-Innenstationen","BCM-Zutrittskontrolle","TCS:BUS-System","Design-Außenstationen"],"sy_en":["TCS video indoor stations","BCM access control","TCS:BUS system","Design outdoor stations"]},{"slug":"fritztower","year":"2023","title_de":"Fritztower, Berlin","title_en":"Fritztower, Berlin","type_de":"Hochhaus","type_en":"High-rise","loc_de":"Berlin-Tiergarten","loc_en":"Berlin-Tiergarten","units_de":"35 Etagen, 375 Apartments","units_en":"35 floors, 375 apartments","desc_de":"Hochhaus-Projekt mit 35 Etagen – TCS-Systeme für Türkommunikation und Gebäudemanagement auf allen Ebenen.","desc_en":"High-rise project with 35 floors – TCS systems for door communication and building management on every level.","body_de":"Der Fritztower ist mit 35 Etagen eines der höchsten Wohngebäude Berlins. Das markante Hochhaus am Tiergarten setzt Maßstäbe für modernes urbanes Wohnen.\n\nDie besondere Herausforderung bestand darin, ein einheitliches Kommunikations- und Zutrittssystem über alle 35 Etagen und 375 Apartments zu implementieren. TCS hat hierfür eine skalierbare BUS-Lösung konzipiert.\n\nDas Gebäudemanagement-System von TCS vernetzt alle Zugangspunkte zentral und ermöglicht eine effiziente Verwaltung. Die Concierge-Funktion im Eingangsbereich ergänzt die technische Infrastruktur.","body_en":"With 35 floors, the Fritztower is one of the tallest residential buildings in Berlin. The striking high-rise at Tiergarten sets standards for modern urban living.\n\nThe particular challenge was to implement a uniform communication and access system across all 35 floors and 375 apartments. To this end, TCS designed a scalable BUS solution.\n\nThe TCS building management system networks all access points centrally and enables efficient administration. The concierge function in the entrance area complements the technical infrastructure.","hl_de":["35-Etagen-Hochhaus-Lösung","375 vernetzte Apartments","Concierge-Integration","Zentrales Gebäudemanagement"],"hl_en":["35-floor high-rise solution","375 networked apartments","Concierge integration","Central building management"],"sy_de":["TCS:BUS-System","Video-Sprechanlagen","Concierge-System","Gebäudemanagement-Software"],"sy_en":["TCS:BUS system","Video intercom systems","Concierge system","Building management software"]},{"slug":"haupttelegraphenamt","year":"2020","title_de":"Haupttelegraphenamt, Berlin","title_en":"Haupttelegraphenamt, Berlin","type_de":"Denkmal / Sanierung","type_en":"Heritage / refurbishment","loc_de":"Berlin-Mitte","loc_en":"Berlin-Mitte","units_de":"120 Einheiten","units_en":"120 units","desc_de":"Denkmalgerechte Sanierung mit Integration moderner TCS-Sprechanlagen in historische Fassaden und Eingangsbereiche.","desc_en":"Heritage-compliant refurbishment with integration of modern TCS intercom systems into historic façades and entrance areas.","body_de":"Das historische Haupttelegraphenamt in Berlin-Mitte ist ein architektonisches Juwel aus der Gründerzeit. Die denkmalgerechte Sanierung stellte höchste Anforderungen an die Integration moderner Technik.\n\nTCS hat für dieses Projekt spezielle Lösungen entwickelt, die sich harmonisch in die historischen Fassaden und Eingangsbereiche einfügen. Die Außenstationen wurden individuell an das Erscheinungsbild des Gebäudes angepasst.\n\nTrotz der denkmalschutzrechtlichen Auflagen konnte ein vollwertiges Video-Türkommunikationssystem installiert werden, das den Bewohnern modernsten Komfort bietet.","body_en":"The historic Haupttelegraphenamt in Berlin-Mitte is an architectural gem from the founding era. The heritage-compliant refurbishment placed the highest demands on the integration of modern technology.\n\nFor this project, TCS developed special solutions that blend harmoniously into the historic façades and entrance areas. The outdoor stations were individually adapted to the appearance of the building.\n\nDespite heritage protection requirements, a fully fledged video door communication system could be installed, offering residents state-of-the-art comfort.","hl_de":["Denkmalgerechte Integration","Individuell angepasste Außenstationen","Historische Fassadenintegration","Moderne Technik im Altbau"],"hl_en":["Heritage-compliant integration","Individually adapted outdoor stations","Historic façade integration","Modern technology in a heritage building"],"sy_de":["Maßgefertigte Außenstationen","TCS:BUS-System","Video-Innenstationen","Unterputz-Montage"],"sy_en":["Custom outdoor stations","TCS:BUS system","Video indoor stations","Flush-mount installation"]},{"slug":"spichern-2","year":"2021","title_de":"Spichern 2, Berlin","title_en":"Spichern 2, Berlin","type_de":"Wohn- und Geschäftshaus","type_en":"Mixed-use building","loc_de":"Berlin-Wilmersdorf","loc_en":"Berlin-Wilmersdorf","units_de":"60 Einheiten","units_en":"60 units","desc_de":"Gemischte Nutzung mit getrennten Zutrittszonen für Gewerbe und Wohnen – realisiert über TCS-Systemtechnik.","desc_en":"Mixed use with separate access zones for commercial and residential tenants – realised with TCS system technology.","body_de":"Spichern 2 in Berlin-Wilmersdorf zeigt, wie moderne Stadtquartiere unterschiedliche Lebens- und Arbeitsbereiche harmonisch vereinen können.\n\nDie besondere Herausforderung lag in der strikten Trennung der Zutrittszonen: Gewerbemieter und Bewohner benötigen separate Zugänge mit individuellen Berechtigungen. TCS hat hierfür ein gestaffeltes Zutrittssystem konzipiert.\n\nÜber die zentrale Verwaltungssoftware lassen sich Berechtigungen flexibel anpassen. Gewerbliche Mieter können beispielsweise nur während der Geschäftszeiten Zugang erhalten, während Bewohner rund um die Uhr Zugriff haben.","body_en":"Spichern 2 in Berlin-Wilmersdorf shows how modern urban quarters can harmoniously combine different living and working areas.\n\nThe particular challenge lay in the strict separation of access zones: commercial tenants and residents need separate entrances with individual permissions. TCS designed a tiered access system for this purpose.\n\nVia the central administration software, permissions can be flexibly adjusted. Commercial tenants, for example, can be granted access only during business hours, while residents have access around the clock.","hl_de":["Getrennte Zutrittszonen","Zeitgesteuerte Berechtigungen","Zentrale Verwaltung","Flexible Konfiguration"],"hl_en":["Separated access zones","Time-controlled permissions","Central administration","Flexible configuration"],"sy_de":["BCM-Zutrittskontrolle","Verwaltungssoftware","TCS:BUS-System","Video-Sprechanlagen"],"sy_en":["BCM access control","Administration software","TCS:BUS system","Video intercom systems"]},{"slug":"thulestrasse","year":"2022","title_de":"Thulestraße, Berlin","title_en":"Thulestraße, Berlin","type_de":"Genossenschaft","type_en":"Cooperative","loc_de":"Berlin-Pankow","loc_en":"Berlin-Pankow","units_de":"45 Einheiten","units_en":"45 units","desc_de":"Genossenschaftliches Wohnprojekt mit barrierefreier TCS-Türkommunikation und altersgerechter Bedienung.","desc_en":"Cooperative residential project with barrier-free TCS door communication and senior-friendly operation.","body_de":"Die Thulestraße in Berlin-Pankow ist ein genossenschaftliches Wohnprojekt, das besonderen Wert auf Barrierefreiheit und altersgerechtes Wohnen legt.\n\nTCS hat speziell für dieses Projekt eine barrierefreie Türkommunikationslösung implementiert. Die Innenstationen verfügen über große Tasten, gut lesbare Displays und eine intuitive Bedienung – ideal für Bewohner aller Altersgruppen.\n\nBesonderer Wert wurde auf akustische und visuelle Signalisierung gelegt: Türrufe werden sowohl optisch als auch akustisch angezeigt und können von Personen mit Höroder Sehbeeinträchtigungen problemlos wahrgenommen werden.","body_en":"Thulestraße in Berlin-Pankow is a cooperative residential project that places special emphasis on accessibility and senior-friendly living.\n\nFor this project, TCS implemented a barrier-free door communication solution. The indoor stations feature large buttons, easy-to-read displays and intuitive operation – ideal for residents of all age groups.\n\nParticular attention was paid to acoustic and visual signalling: door calls are displayed both visually and acoustically and can be easily perceived by people with hearing or visual impairments.","hl_de":["Barrierefreie Bedienung","Große Tasten und Displays","Akustische und visuelle Signale","Altersgerechtes Design"],"hl_en":["Barrier-free operation","Large buttons and displays","Acoustic and visual signals","Senior-friendly design"],"sy_de":["TCS Barrierefreie Stationen","Spezielle Innenstationen","TCS:BUS-System","Akustische Signalgeber"],"sy_en":["TCS barrier-free stations","Special indoor stations","TCS:BUS system","Acoustic signallers"]},{"slug":"quartier-heidestrasse","year":"2023","title_de":"Quartier Heidestraße, Berlin","title_en":"Quartier Heidestraße, Berlin","type_de":"Stadtquartier","type_en":"Urban quarter","loc_de":"Berlin-Mitte","loc_en":"Berlin-Mitte","units_de":"500+ Einheiten","units_en":"500+ units","desc_de":"Großquartier mit über 500 Einheiten – ganzheitliche TCS-Lösung von Türkommunikation bis Smart-Building-Integration.","desc_en":"Large quarter with more than 500 units – holistic TCS solution from door communication to smart building integration.","body_de":"Das Quartier Heidestraße zählt zu den größten urbanen Neubauprojekten Berlins. Mit über 500 Einheiten setzt es Maßstäbe für integriertes, nachhaltiges Wohnen in der Hauptstadt.\n\nTCS lieferte hier eine ganzheitliche Systemlösung: von der Türkommunikation über die Zutrittskontrolle bis zur Smart-Building-Integration. Alle Systeme sind nahtlos vernetzt und zentral verwaltbar.\n\nDie Integration in die übergeordnete Smart-City-Infrastruktur ermöglicht innovative Services für Bewohner, wie Paket-Annahme, Service-Buchungen und energieeffizientes Wohnen.","body_en":"Quartier Heidestraße is one of the largest urban new-build projects in Berlin. With more than 500 units, it sets standards for integrated, sustainable living in the capital.\n\nTCS delivered a holistic system solution here: from door communication and access control through to smart building integration. All systems are seamlessly networked and centrally manageable.\n\nIntegration into the higher-level smart city infrastructure enables innovative services for residents such as parcel reception, service bookings and energy-efficient living.","hl_de":["500+ Einheiten vernetzt","Smart-Building-Integration","Smart-City-Anbindung","Paket-Services integriert"],"hl_en":["500+ units networked","Smart building integration","Smart city connectivity","Integrated parcel services"],"sy_de":["TCS:BUS-System","Smart-Building-Gateway","Zutrittskontrolle","Verwaltungssoftware"],"sy_en":["TCS:BUS system","Smart building gateway","Access control","Administration software"]},{"slug":"luisenpark-residenz","year":"2022","title_de":"Luisenpark Residenz, Berlin","title_en":"Luisenpark Residenz, Berlin","type_de":"Premium-Wohnen","type_en":"Premium living","loc_de":"Berlin-Charlottenburg","loc_en":"Berlin-Charlottenburg","units_de":"75 Wohneinheiten","units_en":"75 residential units","desc_de":"Premium-Wohnanlage mit hochwertiger Design-Sprechanlage und vollständig integrierter Smart-Home-Technik.","desc_en":"Premium residential complex with high-quality design intercom and fully integrated smart home technology.","body_de":"Die Luisenpark Residenz in Berlin-Charlottenburg verkörpert Premium-Wohnen auf höchstem Niveau. Architektur, Innenausstattung und Technik bilden eine perfekte Einheit.\n\nFür dieses anspruchsvolle Projekt entwickelte TCS eine maßgeschneiderte Design-Sprechanlage, deren ästhetische Qualität dem Premium-Anspruch der Anlage entspricht. Die Außenstationen aus Edelstahl mit individueller Beschriftung sind Hingucker an jedem Eingang.\n\nDie vollständige Integration in die Smart-Home-Systeme der Wohnungen ermöglicht den Bewohnern, Türkommunikation, Licht, Beschattung und Klima zentral zu steuern.","body_en":"Luisenpark Residenz in Berlin-Charlottenburg embodies premium living at the highest level. Architecture, interior design and technology form a perfect unity.\n\nFor this demanding project, TCS developed a tailor-made design intercom whose aesthetic quality matches the premium standard of the complex. The stainless-steel outdoor stations with individual lettering are eye-catchers at every entrance.\n\nFull integration into the smart home systems of the apartments allows residents to control door communication, lighting, shading and climate centrally.","hl_de":["Premium-Design-Sprechanlage","Edelstahl-Außenstationen","Vollständige Smart-Home-Integration","Individuelle Beschriftung"],"hl_en":["Premium design intercom","Stainless steel outdoor stations","Full smart home integration","Individual lettering"],"sy_de":["Design-Außenstationen","Premium-Innenstationen","Smart-Home-Gateway","TCS:BUS-System"],"sy_en":["Design outdoor stations","Premium indoor stations","Smart home gateway","TCS:BUS system"]},{"slug":"klinikum-sued","year":"2023","title_de":"Klinikum Süd, München","title_en":"Klinikum Süd, Munich","type_de":"Klinik","type_en":"Clinic","loc_de":"München","loc_en":"Munich","units_de":"450 Patientenzimmer","units_en":"450 patient rooms","desc_de":"Klinikneubau mit 450 Patientenzimmern – TCS-Kommunikationslösung mit Pflegerufsystem-Anbindung.","desc_en":"New hospital build with 450 patient rooms – TCS communication solution with nursing call system connection.","body_de":"Das Klinikum Süd in München ist ein moderner Klinikneubau mit 450 Patientenzimmern. Die Anforderungen an Kommunikation und Sicherheit sind in einem Krankenhaus besonders hoch.\n\nTCS hat hier eine spezielle Kommunikationslösung implementiert, die nahtlos mit dem Pflegerufsystem integriert ist. Patienten können bei Bedarf direkt mit dem Pflegepersonal kommunizieren.\n\nZusätzlich ermöglicht das System eine effiziente Besucherverwaltung und steuert den Zugang zu sensiblen Bereichen wie Operationssälen oder Intensivstationen. Alle Vorgänge werden zentral protokolliert.","body_en":"Klinikum Süd in Munich is a modern new hospital build with 450 patient rooms. The requirements for communication and security in a hospital are particularly high.\n\nTCS has implemented a special communication solution here that is seamlessly integrated with the nursing call system. Patients can communicate directly with the nursing staff when needed.\n\nIn addition, the system enables efficient visitor management and controls access to sensitive areas such as operating theatres or intensive care units. All processes are centrally logged.","hl_de":["Pflegerufsystem-Integration","450 Patientenzimmer vernetzt","Zentrales Sicherheits-Management","Vollständige Protokollierung"],"hl_en":["Nursing call system integration","450 patient rooms networked","Central security management","Complete logging"],"sy_de":["TCS Klinik-Lösung","Pflegerufsystem-Kopplung","Zutrittskontrolle","Verwaltungssoftware"],"sy_en":["TCS clinic solution","Nursing call system coupling","Access control","Administration software"]},{"slug":"rathaus-neustadt","year":"2021","title_de":"Rathaus Neustadt","title_en":"Town hall Neustadt","type_de":"Behörde","type_en":"Public authority","loc_de":"Neustadt","loc_en":"Neustadt","units_de":"120 Büros","units_en":"120 offices","desc_de":"Verwaltungsgebäude mit differenzierten Zutrittsrechten und vollständiger Protokollierung aller Zugänge.","desc_en":"Administrative building with differentiated access rights and complete logging of all accesses.","body_de":"Das Rathaus Neustadt ist das Verwaltungszentrum der Stadt mit 120 Büros und mehreren öffentlich zugänglichen Bereichen.\n\nFür dieses Projekt hat TCS ein komplexes Zutrittskontrollsystem mit differenzierten Berechtigungsstufen implementiert. Mitarbeiter, Besucher und Wartungspersonal haben jeweils individuelle Zugangsrechte zu bestimmten Bereichen.\n\nDie vollständige Protokollierung aller Zugänge erfüllt die strengen Anforderungen an Datenschutz und Nachvollziehbarkeit in einer öffentlichen Einrichtung. Manipulationssichere Lösungen gewährleisten höchste Sicherheit.","body_en":"The town hall Neustadt is the administrative centre of the city with 120 offices and several publicly accessible areas.\n\nFor this project, TCS implemented a complex access control system with differentiated permission levels. Employees, visitors and maintenance staff each have individual access rights to specific areas.\n\nThe complete logging of all accesses meets the strict requirements for data protection and traceability in a public facility. Tamper-proof solutions ensure the highest level of security.","hl_de":["Differenzierte Zutrittsrechte","Vollständige Zugangsprotokollierung","Manipulationssichere Hardware","Datenschutz-Konformität"],"hl_en":["Differentiated access rights","Complete access logging","Tamper-proof hardware","Data protection compliance"],"sy_de":["BCM-Zutrittskontrolle","RFID-Leser","Manipulationssichere Hardware","Audit-Software"],"sy_en":["BCM access control","RFID readers","Tamper-proof hardware","Audit software"]},{"slug":"campus-westend","year":"2022","title_de":"Campus Westend","title_en":"Campus Westend","type_de":"Universität","type_en":"University","loc_de":"Frankfurt","loc_en":"Frankfurt","units_de":"15 Gebäude","units_en":"15 buildings","desc_de":"Universitätscampus mit zentralem Zutrittskontrollsystem für Studierende, Mitarbeiter und Gastdozenten.","desc_en":"University campus with central access control system for students, staff and guest lecturers.","body_de":"Der Campus Westend in Frankfurt umfasst 15 Universitätsgebäude mit unterschiedlichen Nutzungsanforderungen – von Hörsälen über Labore bis zu Verwaltungsbüros.\n\nTCS hat hier ein zentrales Zutrittskontrollsystem implementiert, das alle Gebäude vernetzt. Studierende, Mitarbeiter und Gastdozenten erhalten individuelle Berechtigungskarten mit angepassten Zugangsrechten.\n\nDie zentrale Verwaltung ermöglicht eine effiziente Administration auch bei tausenden Nutzern. Sicherheitskritische Bereiche wie Labore oder Serverräume verfügen über zusätzliche biometrische Zutrittskontrolle.","body_en":"The Campus Westend in Frankfurt comprises 15 university buildings with different usage requirements – from lecture halls and laboratories to administrative offices.\n\nTCS has implemented a central access control system here that networks all buildings. Students, staff and guest lecturers receive individual access cards with adapted access rights.\n\nThe central administration enables efficient management even with thousands of users. Security-critical areas such as laboratories or server rooms are equipped with additional biometric access control.","hl_de":["15 Gebäude vernetzt","Tausende Nutzer verwaltet","Biometrie für sensible Bereiche","Zentrale Administration"],"hl_en":["15 buildings networked","Thousands of users managed","Biometrics for sensitive areas","Central administration"],"sy_de":["BCM-Zutrittskontrolle","Biometrische Leser","Zentrale Verwaltungssoftware","RFID-Karten"],"sy_en":["BCM access control","Biometric readers","Central administration software","RFID cards"]},{"slug":"seniorenresidenz-am-park","year":"2023","title_de":"Seniorenresidenz am Park","title_en":"Senior residence am Park","type_de":"Seniorenwohnen","type_en":"Senior living","loc_de":"Hamburg","loc_en":"Hamburg","units_de":"95 Wohneinheiten","units_en":"95 residential units","desc_de":"Seniorenresidenz mit barrierefreier Türkommunikation und direkter Anbindung an das Pflegerufsystem.","desc_en":"Senior residence with barrier-free door communication and direct connection to the nursing call system.","body_de":"Die Seniorenresidenz am Park in Hamburg ist auf die besonderen Bedürfnisse älterer Bewohner ausgelegt. Komfort, Sicherheit und einfache Bedienbarkeit stehen im Mittelpunkt.\n\nTCS hat hier eine speziell für Senioren konzipierte Türkommunikationslösung implementiert. Die Innenstationen verfügen über besonders große Displays, gut lesbare Beschriftungen und eine intuitive Menüführung.\n\nBesonders wichtig ist die Anbindung an das Pflegerufsystem: Im Notfall können Bewohner über die Sprechanlage direkt das Pflegepersonal erreichen. Die zentrale Verwaltung ermöglicht eine einfache Anpassung bei wechselnden Bewohnern.","body_en":"The senior residence am Park in Hamburg is designed for the special needs of older residents. Comfort, safety and ease of use are at the heart of the project.\n\nFor this project, TCS implemented a door communication solution specifically designed for seniors. The indoor stations are equipped with particularly large displays, easy-to-read labels and intuitive menus.\n\nParticularly important is the connection to the nursing call system: in an emergency, residents can reach the nursing staff directly via the intercom. The central administration allows easy adjustment when residents change.","hl_de":["Große 7-Zoll-Displays","Pflege-Rufsystem-Anbindung","Induktive Hörunterstützung","Einfache Bedienung"],"hl_en":["Large 7-inch displays","Nursing call system connection","Inductive hearing support","Easy operation"],"sy_de":["TCS Barrierefreie Stationen","7-Zoll Video-Innenstationen","Pflege-Rufsystem-Kopplung","TCS:BUS-System"],"sy_en":["TCS barrier-free stations","7-inch video indoor stations","Nursing call system coupling","TCS:BUS system"]}]'::jsonb) LOOP
    pk := 'anwendungen.referenzprojekte.' || (r->>'slug');

    VALUES (pk,'/anwendungen/referenzprojekte/'||(r->>'slug'),'T05',r->>'title_de',r->>'title_en','published',true)
    ON CONFLICT (page_key) DO UPDATE SET route_path=EXCLUDED.route_path,page_type=EXCLUDED.page_type,title_de=EXCLUDED.title_de,title_en=EXCLUDED.title_en,status='published',is_active=true,updated_at=now();

    ON CONFLICT (page_key,section_key) DO UPDATE SET section_type=EXCLUDED.section_type,sort_order=EXCLUDED.sort_order,is_active=true,updated_at=now();

    ON CONFLICT (page_key,section_key,field_key,locale) DO UPDATE SET value=EXCLUDED.value,updated_at=now();

    ON CONFLICT (page_key,section_key,field_key,locale) DO UPDATE SET value_json=EXCLUDED.value_json,updated_at=now();
  END LOOP;
END $mig$;